static ssize_t fc_pause_on_show(struct device *dev,
				struct device_attribute *attr, char *buf)
{
	struct r8152 *tp = netdev_priv(to_net_dev(dev));

	if (!tp->fc_pause_on)
		sprintf(buf, "(Auto)%u\n", fc_pause_on_auto(tp));
	else
		sprintf(buf, "%u\n", tp->fc_pause_on);

	return strlen(buf);
}
